// Плагин стенда: пишет сырые аргументы tool.execute.before целиком, отменяет вызов на маркере.
import fs from 'node:fs';
export const StandProbe = async (ctx) => ({
    'tool.execute.before': async (input, output) => {
        fs.appendFileSync(process.env.STAND_HOOK_LOG, JSON.stringify({ ctx: { directory: ctx.directory, worktree: ctx.worktree }, input, output }) + '\n');
        if (JSON.stringify(output).includes('ralph-stand-forbidden')) throw new Error('blocked by stand plugin');
    },
});

