// Стенд #197: сессия OpenCode с окружением и настройками от сборщика канона (`opencode-home.ts`).
// Исполняется ВНУТРИ стенда (`stand.mts exec`): node drive.mts <канон> <случай>.
// Слои-маркеры: плагин `.opencode/plugin` дерева, npm-плагин `opencode.json` дерева (file://),
// плагин глобального каталога человека, плагин из `OPENCODE_CONFIG_CONTENT` раннера. Барьер —
// плагин стенда в каталоге сессии: отмечает загрузку и отменяет вызов с маркером запрета.
import { spawn, spawnSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

const [canon, caseId] = process.argv.slice(2);
const oh = await import(path.join(canon, 'adapters', 'opencode-home.ts'));
const root = path.dirname(process.env.HOME as string);
const markers = path.join(root, 'markers');
const tree = path.join(root, 'work', 'loop');
const configDir = path.join(root, 'ralph', 'opencode', 'config');
const humanXdg = process.env.XDG_CONFIG_HOME as string;
const journal = path.join(root, 'journal', 'provider.jsonl');
const port = 18500 + (process.pid % 400);
fs.mkdirSync(markers, { recursive: true });
fs.mkdirSync(path.dirname(journal), { recursive: true });

const markerPlugin = (name: string, barrier = false) =>
    `import fs from 'node:fs';\n` +
    `export const P_${name.replace(/\W/g, '_')} = async () => {\n` +
    `    fs.writeFileSync(${JSON.stringify(path.join(markers, name))}, 'loaded');\n` +
    `    return {\n` +
    `        'tool.execute.before': async (input, output) => {\n` +
    `            fs.appendFileSync(${JSON.stringify(path.join(markers, `${name}.calls`))}, input.tool + '\\n');\n` +
    (barrier
        ? `            if (JSON.stringify(output).includes('ralph-stand-forbidden')) throw new Error('blocked by stand barrier');\n`
        : '') +
    `        },\n` +
    `    };\n` +
    `};\n`;
const put = (p: string, text: string) => {
    fs.mkdirSync(path.dirname(p), { recursive: true });
    fs.writeFileSync(p, text);
};

// Дерево: репозиторий, правила, слои проекта.
fs.mkdirSync(tree, { recursive: true });
spawnSync('git', ['init', '-q'], { cwd: tree });
put(path.join(tree, 'AGENTS.md'), '# Правила дерева\n\nRALPH-STAND-RULES-MARKER\n');
put(path.join(tree, '.opencode', 'plugin', 'tree.js'), markerPlugin('tree-dir-plugin'));
const npmLike = path.join(root, 'pkgs', 'tree-json-plugin.js');
put(npmLike, markerPlugin('tree-json-plugin'));
put(path.join(tree, 'opencode.json'), JSON.stringify({ plugin: [`file://${npmLike}`] }));
// Глобальный каталог конфига человека.
put(path.join(humanXdg, 'opencode', 'plugin', 'human.js'), markerPlugin('human-plugin'));
const contentPlugin = path.join(root, 'pkgs', 'content-plugin.js');
put(contentPlugin, markerPlugin('content-plugin'));

// Каталог сессии — как `prepareOpencodeSession`: плагин (здесь — барьер стенда), настройки
// `opencodeSessionConfig` с правилами абсолютным путём. Провайдер — фиктивный, добавлен стендом:
// ключа у стенда нет, и вход CLI здесь заменяет провайдер в настройках сессии.
put(path.join(configDir, 'plugin', 'ralph-guard.js'), markerPlugin('barrier-plugin', true));
fs.mkdirSync(oh.opencodeSessionXdg(configDir), { recursive: true });
const sessionCfg = JSON.parse(
    oh.opencodeSessionConfig({ instructions: [path.join(tree, 'AGENTS.md')] }),
);
sessionCfg.provider = {
    mock: {
        npm: '@ai-sdk/openai-compatible',
        options: { baseURL: `http://127.0.0.1:${port}/v1`, apiKey: 'stand' },
        models: { mock: { name: 'mock', tool_call: true } },
    },
};
put(path.join(configDir, 'opencode.json'), JSON.stringify(sessionCfg, null, 4));

// Окружение раннера: OPENCODE_PURE и вливание конфига с плагином — то, что сборщик обязан снять.
const runnerEnv: NodeJS.ProcessEnv = {
    ...process.env,
    OPENCODE_PURE: '1',
    OPENCODE_CONFIG_CONTENT: JSON.stringify({ plugin: [`file://${contentPlugin}`] }),
};
const env = oh.opencodeSessionEnv(runnerEnv, { configDir, cwd: tree });
if (caseId === 'O-pure') env.OPENCODE_PURE = '1';
// Контроль: `PWD` каталога запуска, как до сборщика с деревом, — каталог сессии CLI берёт из него.
if (caseId === 'O-pwd-stale') env.PWD = root;
if (caseId === 'O-project') {
    delete env[oh.OPENCODE_DISABLE_PROJECT_CONFIG_ENV];
    env[oh.XDG_CONFIG_HOME_ENV] = humanXdg;
}
const isolationProblems = oh.opencodeIsolationProblems({
    env,
    configDir,
    cwd: tree,
    humanXdg,
    forbiddenEnv: ['OPENCODE_PURE', 'OPENCODE_CONFIG_CONTENT', 'OPENCODE_PERMISSION'],
    existsFn: (p: string) => fs.existsSync(p),
});

// Сети у стенда нет: загрузку списка моделей выключает стенд ПОСЛЕ сверки — у сессии петли сеть
// есть, и сборщик эту переменную раннера снимает вместе с прочими `OPENCODE_*`.
env.OPENCODE_DISABLE_MODELS_FETCH = '1';

// Провайдер и вызов: оболочка пишет файл с маркером запрета — барьер обязан отменить её.
const callFile = path.join(root, 'call.json');
put(
    callFile,
    JSON.stringify({
        name: 'bash',
        arguments: {
            command: 'echo ralph-stand-forbidden > forbidden.txt',
            description: 'stand',
        },
    }),
);
const mock = spawn(process.execPath, [path.join(import.meta.dirname, 'mock.mjs'), String(port), callFile, journal], {
    stdio: 'ignore',
});
for (let i = 0; i < 100 && !(fs.existsSync(journal) && fs.readFileSync(journal, 'utf8').includes('ready')); i++)
    await new Promise((r) => setTimeout(r, 50));
const versionBefore = spawnSync('opencode', ['--version'], { env, encoding: 'utf8' }).stdout.trim();
const r = spawnSync('opencode', ['run', '--format', 'json', '-m', 'mock/mock', 'go'], {
    cwd: tree,
    env,
    encoding: 'utf8',
    timeout: 420_000,
});
mock.kill();
const events = r.stdout
    .split('\n')
    .filter(Boolean)
    .map((l) => {
        try {
            return JSON.parse(l);
        } catch {
            return { raw: l };
        }
    });
const tool = events.find((e) => e.type === 'tool_use')?.part?.state;
const requests = fs
    .readFileSync(journal, 'utf8')
    .split('\n')
    .filter((l) => l.startsWith('{"method":"POST"'));
const loaded = fs
    .readdirSync(markers)
    .filter((n) => !n.endsWith('.calls'))
    .sort();
const logDir = path.join(process.env.XDG_DATA_HOME as string, 'opencode', 'log');
const created = fs
    .readdirSync(logDir)
    .flatMap((f) => fs.readFileSync(path.join(logDir, f), 'utf8').split('\n'))
    .find((l) => l.includes('message=created '));
const sessionDirectory = / directory=(\S+)/.exec(created ?? '')?.[1] ?? null;
const strip = (s: string) => s.split(root).join('/path/to/stand');
console.log(
    'STAND-RESULT ' +
        strip(
            JSON.stringify({
                id: caseId,
                cliVersion: versionBefore,
                isolationProblems,
                pluginsLoaded: loaded,
                spawnPwd: env.PWD ?? null,
                sessionDirectory,
                toolStatus: tool?.status ?? null,
                toolError: tool?.error ?? null,
                forbiddenWritten: fs.existsSync(path.join(sessionDirectory ?? tree, 'forbidden.txt')),
                rulesInPrompt: requests.some((l) => l.includes('RALPH-STAND-RULES-MARKER')),
                providerRequests: requests.length,
                exit: r.status === null ? `signal=${r.signal}` : `exit=${r.status}`,
                stderrTail: r.stderr.split('\n').filter(Boolean).slice(-3),
            }),
        ),
);
